/**
 * BEJEWELY: use the standard own-enumerable-key operation, without copied snippets.
 */
util.isEmpty = function(object) {
  return Object.keys(Object(object)).length === 0;
};

/**
 * BEJEWELY: binary-size presentation using a unit table and the retained formatter.
 */
util.formatSize = function(bytes) {
  var units = [[1073741824, 2, '.', '', ' GiB'],
    [1048576, 2, '.', '', ' MiB'], [1024, 0, undefined, undefined, ' KiB'],
    [-Infinity, 0, undefined, undefined, ' bytes']];
  for(var index = 0; index < units.length; ++index) {
    var unit = units[index];
    if(bytes >= unit[0] || index === units.length - 1) {
      var value = index === units.length - 1 ? bytes : bytes / unit[0];
      return util.formatNumber(value, unit[1], unit[2], unit[3]) + unit[4];
    }
  }
};
